# XLWebEngineUI: consume the independently locked, privately built Dawn/Tint closure.
# The upstream CMake actions would rebuild DXC/SwiftShader and mix CRT settings.
import("//gn/skia.gni")
import("//third_party/dawn/args.gni")
declare_args() {
  xl_dawn_include_dirs = []
  xl_dawn_static_library = ""
}
assert(xl_dawn_static_library != "", "Build the locked Dawn closure first")
config("tint_api_config") {
  include_dirs = xl_dawn_include_dirs
  defines = [ "TINT_BUILD_WGSL_READER=1", "TINT_BUILD_WGSL_WRITER=1" ]
  libs = [ xl_dawn_static_library ]
}
group("tint") {
  public_configs = [ ":tint_api_config" ]
}
config("dawn_api_config") {
  include_dirs = xl_dawn_include_dirs
  libs = [ xl_dawn_static_library ]
}
config("dawn_defines") {
  defines = []
  if (dawn_enable_d3d11 && is_win) {
    defines += [ "SK_DAWN_HAS_D3D11" ]
  }
  if (dawn_enable_d3d12 && is_win) {
    defines += [ "SK_DAWN_HAS_D3D12" ]
  }
  if (dawn_enable_vulkan && (is_win || is_android || is_linux)) {
    defines += [ "SK_DAWN_HAS_VULKAN" ]
  }
  if (dawn_enable_opengles) {
    defines += [ "SK_DAWN_HAS_OPENGLES" ]
  }
  if (dawn_enable_metal && (is_mac || is_ios)) {
    defines += [ "SK_DAWN_HAS_METAL" ]
  }
}
group("dawn") {
  public_configs = [ ":dawn_api_config" ]
  all_dependent_configs = [ ":dawn_defines" ]
}

