if (is_debug) {
  sources += skia_sksl_validate_spirv_sources
  if (skia_use_dawn) {
    # XL: Dawn/Tint already owns this exact SPIRV-Tools implementation.
    # Keep validation enabled without compiling/distributing it twice.
    deps += [ "//third_party/dawn:dawn" ]
    if (!defined(include_dirs)) {
      include_dirs = []
    }
    include_dirs += [ "third_party/externals/spirv-tools/include" ]
  } else {
    deps += [
      "//third_party/externals/spirv-tools:spvtools",
      "//third_party/externals/spirv-tools:spvtools_val",
    ]
  }
}
